// Status is why Step returned.
type Status int

const (
	StatusRow       Status = iota // a result row is ready
	StatusDone                    // the program halted
	StatusOutOfFuel               // the fuel budget ran out mid-query; call Step again to continue
)

func (s Status) String() string { return [...]string{"Row", "Done", "OutOfFuel"}[s] }

// State is *everything* a running query is. No pointers into Go stacks, no closures, no open
// iterators — just data. That is what makes Snapshot/Restore possible.
type State struct {
	PC          int
	Halted      bool
	Steps       int // instructions executed so far
	ProgramSize int // sanity check on restore

	Regs    Vals
	Cursors []CursorState
	Hashes  []*HashState
	Sorters []*SorterState
	Aggs    []*AggState
}

// CursorState is a position in a base table. (The data itself isn't state: it's the database.)
type CursorState struct {
	Table string
	Pos   int
}

// HashState is a join hash table plus the probe's position in the current match list.
type HashState struct {
	Buckets  map[string][]Vals
	MatchKey string
	MatchIdx int
}

// SorterState is the rows to sort and the read position once sorted.
type SorterState struct {
	Rows []Vals
	Keys []int
	Desc []bool
	Pos  int
}

// AggState is a hash aggregate: groups in first-seen order, an index by key, and a read position.
type AggState struct {
	Fns       []string // count*, count, sum, min, max, avg
	NKeys     int
	Groups    []*Group
	Index     map[string]int
	Pos       int
	Finalized bool
}

type Group struct {
	Key  Vals
	Accs []Acc
}

// Acc accumulates one aggregate.
type Acc struct {
	Count     int64
	Sum, Best Value
}

// VM runs a Program against a database.
type VM struct {
	prog *Program
	db   DB
	S    State

	// Trace, if set, is called before each instruction executes.
	Trace func(pc int, in Instr, regs Vals)
}

func NewVM(prog *Program, db DB) *VM {
	vm := &VM{prog: prog, db: db}
	vm.S = State{
		ProgramSize: len(prog.Instrs),
		Regs:        make(Vals, prog.NumRegs),
		Cursors:     make([]CursorState, prog.NumCursors),
		Hashes:      make([]*HashState, prog.NumHashes),
		Sorters:     make([]*SorterState, prog.NumSorters),
		Aggs:        make([]*AggState, prog.NumAggs),
	}
	return vm
}

