// Helpers: values, 3VL, aggregates, sorting
// ---------------------------------------------------------------------------------------------

func apply(op string, a, b Value) Value {
	if a == nil || b == nil {
		return nil
	}
	switch op {
	case "Add", "Sub", "Mul", "Div":
		ai, aInt := a.(int64)
		bi, bInt := b.(int64)
		if aInt && bInt && op != "Div" {
			switch op {
			case "Add":
				return ai + bi
			case "Sub":
				return ai - bi
			default:
				return ai * bi
			}
		}
		x, y := toFloat(a), toFloat(b)
		switch op {
		case "Add":
			return x + y
		case "Sub":
			return x - y
		case "Mul":
			return x * y
		}
		if y == 0 {
			return nil
		}
		return x / y
	}
	c := Compare(a, b)
	switch op {
	case "Eq":
		return c == 0
	case "Ne":
		return c != 0
	case "Lt":
		return c < 0
	case "Le":
		return c <= 0
	case "Gt":
		return c > 0
	default:
		return c >= 0
	}
}

func and3(a, b Value) Value {
	if a == false || b == false {
		return false
	}
	if a == nil || b == nil {
		return nil
	}
	return true
}

func or3(a, b Value) Value {
	if a == true || b == true {
		return true
	}
	if a == nil || b == nil {
		return nil
	}
	return false
}

func callFunc(name string, args Vals) Value {
	if name == "coalesce" {
		for _, a := range args {
			if a != nil {
				return a
			}
		}
		return nil
	}
	if args[0] == nil {
		return nil
	}
	switch name {
	case "lower":
		return strings.ToLower(args[0].(string))
	case "upper":
		return strings.ToUpper(args[0].(string))
	case "length":
		return int64(len(args[0].(string)))
	case "abs":
		if i, ok := args[0].(int64); ok {
			if i < 0 {
				return -i
			}
			return i
		}
		return math.Abs(args[0].(float64))
	}
	panic("unknown function " + name)
}

func (a *Acc) step(fn string, v Value) {
	if fn == "count*" {
		a.Count++
		return
	}
	if v == nil {
		return
	}
	a.Count++
	switch fn {
	case "sum", "avg":
		if a.Sum == nil {
			a.Sum = v
		} else if x, ok := a.Sum.(int64); ok {
			if y, ok := v.(int64); ok {
				a.Sum = x + y
				break
			}
			a.Sum = float64(x) + toFloat(v)
		} else {
			a.Sum = toFloat(a.Sum) + toFloat(v)
		}
	case "min":
		if a.Best == nil || Compare(v, a.Best) < 0 {
			a.Best = v
		}
	case "max":
		if a.Best == nil || Compare(v, a.Best) > 0 {
			a.Best = v
		}
	}
}

func (a *Acc) result(fn string) Value {
	switch fn {
	case "count", "count*":
		return a.Count
	case "sum":
		return a.Sum
	case "avg":
		if a.Count == 0 {
			return nil
		}
		return toFloat(a.Sum) / float64(a.Count)
	}
	return a.Best
}

// less orders sorter records by their key columns; NULLs last in both directions.
func (st *SorterState) less(a, b Vals) bool {
	for i, k := range st.Keys {
		x, y := a[k], b[k]
		switch {
		case x == nil && y == nil:
			continue
		case x == nil:
			return false
		case y == nil:
			return true
		}
		c := Compare(x, y)
		if st.Desc[i] {
			c = -c
		}
		if c != 0 {
			return c < 0
		}
	}
	return false
}

// String renders the VM's position for demos.
func (vm *VM) String() string {
	return fmt.Sprintf("pc=%d steps=%d halted=%v", vm.S.PC, vm.S.Steps, vm.S.Halted)
}
